L["1 profile on this account"] = "1 perfil en esta cuenta"
L["1 raid"] = "1 banda"
L["1 runs Naowh Forever"] = "1 usa Naowh Forever"
L["1 setting changed from its default"] = "1 opción cambiada respecto a su valor predeterminado"
L["1 spell"] = "1 hechizo"
L["1 Unspent Talent Point"] = "1 punto de talento sin gastar"
L["1. PICK YOUR BARS"] = "1. ELIGE TUS BARRAS"
L["100%  (default)"] = "100%  (predeterminado)"
L["100%, native resolution"] = "100%, resolución nativa"
L["12-hour clock"] = "Reloj de 12 horas"
L["16x Anisotropic"] = "Anisotrópico 16x"
L["2. ALSO KEEP"] = "2. CONSERVAR TAMBIÉN"
L["24-Hour Clock"] = "Reloj de 24 horas"
L["24-hour clock"] = "Reloj de 24 horas"
L["3. NAME AND SAVE"] = "3. NOMBRA Y GUARDA"
L["30, while the game is not in focus"] = "30, mientras el juego no está en primer plano"
L[": copy ID or Wowhead link"] = ": copiar ID o enlace de Wowhead"
L[": mail expiring soon on "] = ": correo a punto de caducar en "
L["; buys at vendors"] = "; compra en vendedores"
L["<AFK>"] = "<Ausente>"
L["<DND>"] = "<No molestar>"
L["[Where?]"] = "[¿Dónde?]"
L["A /thank to everyone around you when the game cannot name the caster."] = "Un /thank a todos los que te rodean cuando el juego no puede nombrar al lanzador."
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "Un enlace [¿Dónde?] tras un susurro de alguien cuya zona no se conoce. Al hacer clic ejecuta un /who sobre esa persona y muestra su zona; sus siguientes mensajes se etiquetan."
L["A banner and a sound when one of them joins your group."] = "Un aviso y un sonido cuando uno de ellos se une a tu grupo."
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "Una barra en la amenaza a la que quitarías el aggro, para ver fácilmente cuánto falta."
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "Una barra para los golpes de tu objetivo, que se reinicia con cada golpe físico que recibes mientras te tiene como objetivo y se acorta cuando para. Es una estimación: el juego no dice quién te golpeó ni con qué, así que otros atacantes, ataques especiales físicos y tics de sangrado también la reinician."
L["A bar left out is not touched by an import."] = "Una barra que se deja fuera no se toca al importar."
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "Una barra por miembro del grupo con su nivel y cuánto llevan de él. Cada miembro que use Naowh Forever comparte su experiencia, aunque esto esté desactivado; los demás muestran su nivel. Se actualiza al terminar el combate. Muévela en el Editor de HUD."
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "Una barra con el nombre, una flecha de giro y la distancia mientras haya un punto de ruta."
L["A batch of ten, four done, as it shows while you craft."] = "Una tanda de diez, cuatro hechos, como se ve mientras fabricas."
L["A black outline round the clock."] = "Un contorno negro alrededor del reloj."
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "Un contorno negro alrededor de los FPS / MS y los recuentos, en lugar de la sombra suave."
L["A black outline round the text, in place of the soft shadow."] = "Un contorno negro alrededor del texto, en lugar de la sombra suave."
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "Un botón por conjunto: clic para equiparlo, Mayús+clic para guardar en él lo que llevas, Ctrl+clic para renombrarlo, clic derecho para cambiar su icono y + para guardar uno nuevo. El conjunto que llevas aparece resaltado. Muévelo en el Editor de HUD."
L["A button that flags or unflags you for PvP, showing which you are."] = "Un botón que activa o desactiva tu JcJ y muestra cuál tienes."
L["A campfire in range and Camp Benefits about to run out."] = "Una hoguera al alcance y Beneficios de campamento a punto de acabarse."
L["A campfire in range and no Camp Benefits."] = "Una hoguera al alcance y sin Beneficios de campamento."
L["A campfire is in range"] = "Hay una hoguera al alcance"
L["A card behind the text, a soft dark fade, or nothing at all."] = "Una tarjeta tras el texto, un fundido oscuro suave o nada."
L["A card over the pin with what it is and how far."] = "Una tarjeta sobre el marcador con lo que es y a qué distancia está."
L["A cast part way through, swept around the ring."] = "Un lanzamiento a medias, barrido alrededor del anillo."
L["A cast someone interrupted, held for the fade time."] = "Un lanzamiento que alguien interrumpió, mostrado durante el tiempo de desvanecimiento."
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "Un lanzamiento mientras tu interrupción está en reutilización, con la marca de cuándo vuelve."
L["A cast while your interrupt is ready."] = "Un lanzamiento mientras tu interrupción está lista."
L["A cast you cannot interrupt, with its shield."] = "Un lanzamiento que no puedes interrumpir, con su escudo."
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "Un personaje aparece aquí después de conectarte con él con el Registro de instancias activado. Seguir alters muestra los demás: experiencia de descanso y durabilidad, de la última vez que se conectó ese personaje."
L["A choice among its rewards: pick this one."] = "Una elección entre sus recompensas: escoge esta."
L["A command name can only use letters, numbers and underscores."] = "Un nombre de comando solo puede usar letras, números y guiones bajos."
L["A consumable or personal buff with less time than this left counts as missing."] = "Un consumible o beneficio personal al que le quede menos de este tiempo cuenta como ausente."
L["A crosshair at the middle of your screen."] = "Un punto de mira en el centro de la pantalla."
L["A cup beside a healer who is drinking."] = "Una copa junto a un sanador que está bebiendo."
L["A custom command can't reload. Type /reload."] = "Un comando personalizado no puede recargar. Escribe /reload."
L["A dark or light fill and edge behind each line, or none."] = "Un relleno y borde oscuro o claro tras cada línea, o ninguno."
L["A dark panel behind the icons."] = "Un panel oscuro tras los iconos."
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "Una puerta en cada entrada de mazmorra y banda en el mapa del mundo, para los bandos que indica el Diario. Pasa el cursor para ver los niveles, haz clic para un punto de ruta."
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "Un punto en una casilla donde hay un encantamiento mejor para tu nivel: pasa el cursor para ver el consejo, haz clic para pedirlo en Comercio."
L["A fading trail behind the cursor."] = "Una estela que se desvanece tras el cursor."
L["A few quick steps for %s only, its own modules included."] = "Unos pasos rápidos solo para %s, incluidos sus propios módulos."
L["A game that opens when a flight starts and closes when you land."] = "Un juego que se abre al empezar un vuelo y se cierra al aterrizar."
L["A game to pass the flight: the Quiz or the Aim Trainer. It closes when you land."] = "Un juego para pasar el vuelo: el test o el entrenador de puntería. Se cierra al aterrizar."
L["A gear set called %s already exists."] = "Ya existe un conjunto de equipo llamado %s."
L["A glow on the moving edge of the fill."] = "Un brillo en el borde móvil del relleno."
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "Una cadena de misiones oculta por Azeroth: haz clic en cada cosa del mundo por orden. Da mucha experiencia y termina en el Saco de dormir acogedor; descansa en él para obtener una bonificación de experiencia."
L["A key that opens Group Inspect."] = "Una tecla que abre la Inspección de grupo."
L["A key that shows a boss's loot at your cursor."] = "Una tecla que muestra el botín de un jefe junto al cursor."
L["A key that uses this item."] = "Una tecla que usa este objeto."
L["A later point needs it. "] = "Un punto posterior lo necesita. "
L["A later step."] = "Un paso posterior."
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "Una línea por cada misión que entregas, con la experiencia y el dinero que dio. Los objetos de recompensa aparecen en su propia línea."
L["A line for every reputation gain, from quests and kills alike."] = "Una línea por cada ganancia de reputación, de misiones y de muertes."
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "Una línea con la experiencia de cada muerte. La experiencia de misiones va en la línea de la propia misión."
L["A line from the pin down to a map pin's or corpse's spot."] = "Una línea desde el marcador hasta el punto de un marcador del mapa o de un cadáver."
L["A line in chat with the item's link."] = "Una línea en el chat con el enlace del objeto."
L["A line in their color on their player tooltip."] = "Una línea de su color en la descripción del jugador."
L["A line to share them with."] = "Una línea para compartirlos."
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "Una línea bajo la ID que indica qué teclas la copian (Ctrl+Mayús+C: copiar ID o enlace de Wowhead). Desactivada, el atajo sigue funcionando; solo no se muestra la línea."
L["A look you do not have yet|r"] = "Un aspecto que aún no tienes|r"
L["a macro made on this character"] = "una macro creada en este personaje"
L["A macro this character does not have yet: the import makes it."] = "Una macro que este personaje aún no tiene: la importación la crea."
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "Un botón del minimapa que abre %s. /nf%s hace lo mismo, y la barra superior también puede llevarlo. Guardado para este ordenador."
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Una línea de pesos de Naowh o una exportación EP de WoWSims (en WoWSims: Stat Weights, Copy to Current EP, Export)"
L["A Naowh weights line, or a WoWSims EP export."] = "Una línea de pesos de Naowh o una exportación EP de WoWSims."
L["A new session, before any experience."] = "Una sesión nueva, antes de ganar experiencia."
L["A parry by your target took 40% off its swing."] = "Una parada de tu objetivo le ha quitado un 40% a su golpe."
L["A party of five, a card each."] = "Un grupo de cinco, una tarjeta cada uno."
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "La puntuación de un jugador en su descripción. Quien use Naowh Forever comparte la suya; la de los demás se lee de su equipo al pasar el cursor, dentro del alcance de inspección y fuera de combate."
L["A profile"] = "Un perfil"
L["a quest"] = "una misión"
L["A quest reward for the other faction; try the Auction House."] = "Una recompensa de misión de la otra facción; prueba en la casa de subastas."
L["A raid for %d players"] = "Una banda de %d jugadores"
L["A raid, a row each."] = "Una banda, una fila cada uno."
L["A rare someone else is fighting."] = "Un raro con el que está luchando otra persona."
L["A rare you have killed before."] = "Un raro que ya has matado antes."
L["A rare you have not killed yet."] = "Un raro que aún no has matado."
L["A reward from the quest "] = "Una recompensa de la misión "
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "Un anillo alrededor del cursor para no perderlo nunca en un combate caótico, con tu tiempo de reutilización global y tus lanzamientos barridos a su alrededor."
L["A round in progress."] = "Una ronda en curso."
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "Una fila de iconos para los beneficios de comida, frasco, elixir y pergamino que faltan, tu propio beneficio de clase y los beneficios de clase que faltan en tu grupo. Solo fuera de combate: en combate el juego no deja a los addons ver tus beneficios, así que los iconos mantienen lo que mostraban. Pasa el cursor por uno para elegir un objeto que llevas y usarlo. Muévelos en el Editor de HUD."
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "Un contador de oro por hora junto a la línea más reciente, que cuenta el dinero y el valor de los objetos desde tu primer botín de la sesión."
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "Un botón Escanear precios en la casa de subastas. Lee todos los anuncios y guarda la compra inmediata más baja de cada objeto, para este reino y facción. Blizzard permite un escaneo completo cada 15 minutos."
L["A junk icon on the bag slot of each item marked as junk."] = "Un icono de basura en la casilla de la bolsa de cada objeto marcado como basura."
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "Un segundo panel para tu foco, para controlar el tiempo de Aporrear o Polimorfia sobre un enemigo mientras luchas contra otro."
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "Un conjunto que se pone solo mientras vas montado o descansas, y el que llevabas vuelve después."
L["A shooting game for flights: click the other faction's races as fast as you can."] = "Un juego de disparos para los vuelos: haz clic en las razas de la otra facción lo más rápido que puedas."
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "Un breve destello de texto al entrar y salir de combate. Muévelo en el Editor de HUD."
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "Una pequeña barra con tu próxima visita al instructor y tu oro, para dejarla visible mientras subes de nivel. Muévela arrastrándola."
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "Una pequeña barra de salud para el otro tanque de tu grupo, visible mientras tanqueas: rol de tanque, Forma de oso, Actitud defensiva o Furia recta. El otro tanque es quien tenga el rol de tanque o la asignación de tanque principal de la banda. Haz clic para seleccionarlo. Los cambios en combate se aplican al terminar el combate. Muévela en el Editor de HUD."
L["A soft glow around Naowh's arrow."] = "Un brillo suave alrededor de la flecha de Naowh."
L["A soft glow beside each icon."] = "Un brillo suave junto a cada icono."
L["A soft glow round it in your accent color."] = "Un brillo suave a su alrededor con tu color de acento."
L["A soft glow round it in your rank's color."] = "Un brillo suave a su alrededor con el color de tu rango."
L["A soft ring pulses around each target."] = "Un anillo suave pulsa alrededor de cada objetivo."
L["a sound to refresh"] = "un sonido para renovar"
L["A sound, or the Speech text read aloud, as each cast starts."] = "Un sonido, o el texto de voz leído en alto, al empezar cada lanzamiento."
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "Un sonido, o el texto de voz leído en alto. La conversión de texto a voz puede dar tirones en algunos PC, ya que el juego espera mientras Windows la reproduce; un sonido no cuesta nada."
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "Un hechizo que una importación no pudo colocar porque aún no lo conoces va a su casilla guardada cuando lo aprendes, salvo que hayas puesto otra cosa ahí."
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "Un botón Apilar en la tarjeta cuando se pueden combinar montones incompletos de un objeto."
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "Una estrella en el mapa del mundo por cada raro que no has matado, donde es más probable que esté. Pasa el cursor por una para ver el raro y su botín, sus otros puntos de aparición y, si patrulla, su ruta; haz clic para un punto de ruta, clic derecho para mantener visibles sus puntos y su ruta."
L["A string to share it with."] = "Una cadena para compartirla."
L["A supporter"] = "Un mecenas"
L["A team member"] = "Un miembro del equipo"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "Un texto en la barra: haz clic en él en la vista previa para cambiarlo. Cada texto aparece en un solo lugar de la barra: elegir uno que ya se muestra en otro sitio lo mueve ahí."
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "Una marca en la barra donde tu interrupción sale de reutilización. Oculta mientras está lista."
L["A title bar naming the mob the threat is on."] = "Una barra de título con el nombre del enemigo sobre el que está la amenaza."
L["A trained spell drops into its saved slot."] = "Un hechizo entrenado va a su casilla guardada."
L["a vendor sells the formula"] = "un vendedor vende la fórmula"
L["A warning when a rare is near"] = "Un aviso cuando hay un raro cerca"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "Un aviso cuando hay un raro cerca de ti: cuando aparece su placa de nombre, pasas el cursor por encima o lo seleccionas. Una tarjeta con su retrato: clic derecho para cerrarla; su marcador pone un punto de ruta al raro. Muévela en el Editor de HUD."
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "Un aviso mientras un cazador o brujo no tiene la mascota fuera. Un brujo que ha sacrificado a su demonio no recibe aviso. Muévelo en el Editor de HUD."
L["A word of your own on the icon."] = "Una palabra tuya sobre el icono."
L["A world drop from %d kinds of mob"] = "Botín del mundo de %d |4tipo de enemigo:tipos de enemigo;"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "Un test de WoW para hogueras y vuelos, o en cualquier momento con /naowh quiz."
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "Un ! amarillo en el mapa del mundo en cada dador de misión con una misión que puedes recoger y que aún da experiencia. Pasa el cursor para ver las misiones; haz clic para un punto de ruta."
L["A zone older than this is no longer shown, since the player has likely moved on."] = "Una zona más antigua que esto ya no se muestra, ya que el jugador probablemente se ha ido."
L["Abandon %s?"] = "¿Abandonar %s?"
L["Abilities"] = "Habilidades"
L["about "] = "unos "
L["about %d:%02d"] = "unos %d:%02d"
L["About %s at your last scan%s%s"] = "Unos %s en tu último escaneo%s%s"
L["About %s spent"] = "Unos %s gastados"
L["About a minute."] = "Un minuto aproximadamente."
L["Above"] = "Encima"
L["Acc."] = "Prec."
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "Acento: falta la bendición de clase. Más claro: se está acabando. Más intenso: solo jugadores con la suya propia."
L["Accept Quests"] = "Aceptar misiones"
L["Accept Shared Dungeon Quests"] = "Aceptar misiones de mazmorra compartidas"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "Acepta una misión en cuanto se abre su texto. Usa el modificador para leerla antes."
L["Accepts dungeon quests your group shares with you straight away."] = "Acepta al instante las misiones de mazmorra que tu grupo comparte contigo."
L["Accepts shared quests"] = "Acepta misiones compartidas"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "Acepta la ventana emergente en pantalla: una invocación, una resurrección, una invitación a grupo."
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "Acepta, entrega y comparte misiones por ti, y recuerda la recompensa que guardaste para una misión. El modificador las omite o las activa, según lo que indique Acción del modificador."
L["Account"] = "Cuenta"
L["Account "] = "Cuenta "
L["Account macros"] = "Macros de la cuenta"
L["Account this hour: %d of %d"] = "Cuenta en esta hora: %d de %d"
L["Accuracy"] = "Precisión"
L["Action Bars is switched off."] = "Barras de acción está desactivado."
L["Action Bars' own window, with your class's saved sets."] = "La ventana propia de Barras de acción, con los conjuntos guardados de tu clase."
L["Active"] = "Activo"
L["Activity Bar"] = "Barra de actividad"
L["Activity Bar Color"] = "Color de la barra de actividad"
L["Activity Bar Height"] = "Altura de la barra de actividad"
L["Add %d item to your junk list: %s%s?"] = "¿Añadir %d objeto a tu lista de basura: %s%s?"
L["Add %d items to your junk list: %s%s?"] = "¿Añadir %d objetos a tu lista de basura: %s%s?"
L["Add %d macro as character macros?%s"] = "¿Añadir %d macro como macro de personaje?%s"
L["Add %d macros as character macros?%s"] = "¿Añadir %d macros como macros de personaje?%s"
L["Add %s"] = "Añadir %s"
L["Add %s (%d items) as a new BiS list?"] = "¿Añadir %s (%d objetos) como nueva lista BiS?"
L["Add %s to the Consumable Bar?"] = "¿Añadir %s a la barra de consumibles?"
L["Add a backup pick"] = "Añadir una opción de reserva"
L["Add a Button"] = "Añadir un botón"
L["Add a stat"] = "Añadir una estadística"
L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Añade una ID de objeto o importa una lista. La comida cuenta cualquier beneficio Bien alimentado y otros objetos su propio beneficio; añade ID de hechizos de beneficio solo para un objeto que dé otro. No se añade nada automáticamente. Pasa el cursor por un recordatorio para elegir un objeto configurado de tus bolsas. Los recordatorios se pausan en combate; los menús de objetos funcionan fuera de combate. Cuándo y dónde se muestran está en AuraBuffs > Configuración."
L["Add consumables, put them in order, and set each one up."] = "Añade consumibles, ordénalos y configura cada uno."
L["Add Items"] = "Añadir objetos"
L["Add Latency"] = "Añadir latencia"
L["Add macros someone shared with you."] = "Añade macros que alguien ha compartido contigo."
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "Añade o quita tus comandos, activa o desactiva cada uno o restaura los predeterminados."
L["Add Slash Command"] = "Añadir comando de barra"
L["Add the %s build %s (%d points)?"] = "¿Añadir la build de %s %s (%d puntos)?"
L["Add the consumables to watch in the AuraBuffs window."] = "Añade los consumibles que vigilar en la ventana de AuraBuffs."
L["Add Themes to RestedXP"] = "Añadir temas a RestedXP"
L["Add to BiS List"] = "Añadir a la lista BiS"
L["Add to Shopping List"] = "Añadir a la lista de la compra"
L["Add to the Left Side"] = "Añadir a la izquierda"
L["Add to the Right Side"] = "Añadir a la derecha"
L["Add your consumables, put them in order, set each one up."] = "Añade tus consumibles, ordénalos y configura cada uno."
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "Añade tus propias líneas a las macros de bolsa. Se mantienen después del objeto, tengas lo que tengas en las bolsas."
L["Added %d consumable to the Consumable Bar."] = "Se ha añadido %d consumible a la barra de consumibles."
L["Added %d consumables to the Consumable Bar."] = "Se han añadido %d consumibles a la barra de consumibles."
L["Added %d consumables; %d were already listed or past the %d limit."] = "Se han añadido %d consumibles; %d ya estaban en la lista o superaban el límite de %d."
L["Added %d of %d: %s."] = "Añadidos %d de %d: %s."
L["Added %d."] = "Añadidos %d."
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "%s añadida a este personaje. Arrástrala a una barra desde la ventana de macros del juego (/macro)."
L["Added %s to your BiS %s as #%d."] = "%s añadido a tu BiS de %s como n.º %d."
L["Added %s to your BiS %s."] = "%s añadido a tu BiS de %s."
L["Added next to your Library, never over it"] = "Se añade junto a tu biblioteca, nunca encima"
L["Added next to your own lists, never over them"] = "Se añade junto a tus propias listas, nunca encima"
L["Added next to your saved builds"] = "Se añade junto a tus builds guardadas"
L["Adding Items"] = "Añadiendo objetos"
L["Addon Font"] = "Fuente del addon"
L["Addon List"] = "Lista de addons"
L["Addon Memory"] = "Memoria de addons"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "Añade \"- [1] + Añadir a la lista\" bajo los componentes de una receta: los materiales que Comprar en subasta compraría para esa cantidad de fabricaciones van a una lista de la compra, desde cualquier lugar. En la casa de subastas la lista aparece al lado: Comprobar precios busca cada uno y avisa en rojo cuando uno está muy por encima de tu último escaneo; después Comprar todo recorre la lista material a material, comprando cada uno solo cuando confirmas su precio final. Un material que puedes fabricar más barato con sus partes, como una barra a partir de mineral, se compra por partes."
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "Añade una columna Bolsas a los componentes de la receta elegida, con cuántos de cada uno llevas."
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "Añade una columna Banco a los componentes de la receta elegida, con cuántos de cada uno hay en tu banco."
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "Añade un botón a la ventana que cambia cada rango inferior de tus barras por el rango más alto que conoces. Las barras de teclado y de mando van a la misma casilla. Haz clic derecho en un hechizo de la ventana para conservar sus rangos inferiores y usarlos de forma deliberada. Los cambios de rango solo ocurren fuera de combate."
L["Adds a Land button to come down at the next stop on the way."] = "Añade un botón Aterrizar para bajar en la siguiente parada del trayecto."
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "Añade una línea que marca cualquier casilla cuyo encantamiento falte o difiera de los que capturaste con Capturar encantamientos actuales. Pasa el cursor para ver los detalles."
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "Añade a la descripción de un hechizo de maná su sanación o daño por maná y por segundo."
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "Añade un segundo número naranja junto a cada receta: cuántas podrías hacer tras comprar los componentes que venden los vendedores, como Fundente débil o Hilo grueso. Los componentes de la receta indican entonces cuántos comprar de cada uno."
L["Adds how long the visit lasted."] = "Añade cuánto duró la visita."
L["Adds target and focus switching to the meter's title bar."] = "Añade el cambio de objetivo y foco a la barra de título del medidor."
L["Adds the average experience here."] = "Añade la experiencia media aquí."
L["Adds the coins looted."] = "Añade las monedas despojadas."
L["Adds the consumables in your bags that are not on the bar yet."] = "Añade los consumibles de tus bolsas que aún no están en la barra."
L["Adds the deaths."] = "Añade las muertes."
L["Adds the experience gained."] = "Añade la experiencia ganada."
L["Adds the materials for one more craft."] = "Añade los materiales para una fabricación más."
L["Adds the Naowh themes to RestedXP's theme list."] = "Añade los temas de Naowh a la lista de temas de RestedXP."
L["Adds the reputation gained."] = "Añade la reputación ganada."
L["Adds the visits at this level."] = "Añade las visitas a este nivel."
L["Adds the visits until you level."] = "Añade las visitas hasta que subas de nivel."
L["Adds your bonus healing or spell damage; off shows the spell's base numbers."] = "Añade tu bonificación de sanación o daño de hechizos; desactivado muestra los números base del hechizo."
