L["After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars."] = "Tras visitar a un instructor, una pequeña ventana muestra las habilidades que acabas de aprender. Las habilidades de un libro o una misión aparecen un momento después de aprenderlas. Arrastra una de la ventana a tus barras."
