L["Also a grey ! for quests you can still pick up that no longer give experience."] = "También un ! gris para misiones que aún puedes recoger pero que ya no dan experiencia."
L["Also a grey star on the map for the rares you have killed."] = "También una estrella gris en el mapa para los raros que has matado."
