L["Also keeps your last whispers and group chat lines with each player."] = "También guarda tus últimos susurros y líneas de chat de grupo con cada jugador."
L["Also opens the world map on the waypoint, so you see where it is. Out of combat only."] = "También abre el mapa del mundo en el punto de ruta, para que veas dónde está. Solo fuera de combate."
L["Also prints the summary when you leave a raid."] = "También muestra el resumen al salir de una banda."
L["Also reminds you inside instances. Off by default: few have herbs or ore."] = "También te lo recuerda dentro de instancias. Desactivado por defecto: pocas tienen hierbas o mineral."
L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "También muestra el beneficio de cada receta a la derecha de su fila en la lista, en verde o rojo. Las recetas cuyo beneficio no se conoce no muestran nada."
L["Also thanks players in your party or raid."] = "También da las gracias a jugadores de tu grupo o banda."
L["Also used inside dungeons and raids."] = "También se usa dentro de mazmorras y bandas."
L["Also warns about rares you have killed before."] = "También avisa de raros que ya has matado antes."
L["Also warns while your pet is set to passive."] = "También avisa mientras tu mascota está en modo pasivo."
