L["Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest in this profile; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you."] = "Alt+clic en una recompensa que puedes elegir, en el registro de misiones o en el dador, para guardarla para esa misión en este perfil; Alt+clic de nuevo para borrarla. Se selecciona al entregar la misión, y Entregar misiones la coge por ti."
L["Alt-click an item in your bags to mark it as junk, and sell it at the next vendor."] = "Alt+clic en un objeto de tus bolsas para marcarlo como basura y venderlo en el siguiente vendedor."
