L["At a profession trainer who teaches any of your favourite recipes that you can learn now (star one before its name, or right-click it in the list), a window beside the trainer's lists them with their cost: Learn one, or Learn All."] = "En un instructor de profesión que enseñe alguna de tus recetas favoritas que puedes aprender ya (marca una con estrella antes de su nombre o haz clic derecho en ella en la lista), una ventana junto al instructor las lista con su coste: Aprender una o Aprender todo."
L["At a vendor who sells them, tops your class reagents and ammo up to what you carry, and prints what it spent. Off by default: it spends gold for you."] = "En un vendedor que los venda, repone tus componentes de clase y munición hasta lo que sueles llevar y muestra lo que ha gastado. Desactivado por defecto: gasta oro por ti."
L["At level %d"] = "A nivel %d"
L["At login, names any of your characters with mail that expires within three days. It knows each character's mail from the last time it opened a mailbox."] = "Al conectarte, nombra a cualquiera de tus personajes con correo que caduca en tres días. Conoce el correo de cada personaje de la última vez que abrió un buzón."
L["At the auction house, a window beside it lists the patterns, plans and manuals of your favourite recipes that you have not learned or bought, with what they cost now. Buy finds the cheapest and asks before Accept buys it."] = "En la casa de subastas, una ventana al lado lista los patrones, diseños y manuales de tus recetas favoritas que no has aprendido ni comprado, con lo que cuestan ahora. Comprar busca el más barato y pregunta antes de que Aceptar lo compre."
