L["Each class's name or icon, under its button or beside it when the bar is vertical."] = "El nombre o icono de cada clase, bajo su botón o al lado cuando la barra es vertical."
L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "Cada visita a mazmorra o banda con el Registro de instancias activado: cuánto tiempo estuviste dentro, las monedas que despojaste y la experiencia que ganaste. La reputación ganada aparece bajo la visita. Volver al mismo grupo dentro de la hora, antes de reiniciarla, continúa esa visita, y el tiempo fuera no cuenta. Los demás personajes se quedan guardados y aparecen aquí con Seguir alters activado. Las reparaciones y ventas a vendedores no cuentan. Las visitas más antiguas salen por el final de la lista."
L["Each line fades out after %ss."] = "Cada línea se desvanece tras %ss."
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "Cada una es una macro de cuenta. Ponla en una barra una vez y se mantiene al día sola: despoja una poción mejor, conjura comida nueva o recoge vendas y la macro se reescribe para usar lo mejor que lleves.\n\nEl juego no deja que las macros cambien en mitad de un combate, así que un cambio en combate espera a que termine."
L["Each point of the trail in a color of its own."] = "Cada punto de la estela con un color propio."
L["Each slot's item level, in its icon's corner."] = "El nivel de objeto de cada casilla, en la esquina de su icono."
L["Each visit, with its time, coins, and experience."] = "Cada visita, con su tiempo, monedas y experiencia."
L["Earned in"] = "Se obtiene en"
L["Eats the food on the bar."] = "Come la comida de la barra."
