L["Makes this recipe a favourite, or no longer one. Favourites get a star in the list, and the Filter menu's Favorites shows only them. Right-click a recipe in the list does the same."] = "Marca esta receta como favorita o la desmarca. Las favoritas tienen una estrella en la lista, y Favoritos en el menú Filtro muestra solo esas. Clic derecho en una receta de la lista hace lo mismo."
L["Makes this recipe a favourite, or no longer one. With Train Favorites on, a trainer who teaches it offers it when you visit; with Search Favorites AH on, its pattern, plans or manual is listed at the auction house to search for."] = "Marca esta receta como favorita o la desmarca. Con Entrenar favoritas activado, un instructor que la enseñe te la ofrece al visitarlo; con Buscar favoritas en subasta activado, su patrón, diseño o manual aparece en la casa de subastas para buscarlo."
