L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "Una vez escaneada la casa de subastas (Escanear precios), la receta elegida muestra lo que cuesta comprar sus componentes, por cuánto se vende el objeto y el beneficio tras la comisión del 5% de la casa de subastas. Cada componente se valora a su precio más barato: el de un vendedor una vez lo hayas visto venderlo o, si no, la compra inmediata más baja de tu último escaneo. Desmarca un componente que ya tengas para dejarlo fuera del coste, en todas las recetas que lo usen. Pasa el cursor por las líneas para ver el desglose."
L["One addon"] = "Un addon"
