L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "Abre en esta ventana el enlace de profesión de otro jugador, para encargarle fabricaciones. Elige una receta, indica cuántas fabricaciones, marca los materiales que aportas (o escribe cuántos) y pulsa Añadir al pedido. El pedido de la derecha tiene una propina sugerida por fabricación que puedes cambiar; Pedir envía al artesano un mensaje por fabricación con la cantidad, tus materiales y la propina: por el chat de grupo si está en tu grupo o, si no, como susurro. Los precios y la propina necesitan un escaneo de la casa de subastas."
L["Opens its settings and leaves the HUD Editor."] = "Abre su configuración y sale del Editor de HUD."
L["Opens the Aim Trainer now, out of combat."] = "Abre ahora el entrenador de puntería, fuera de combate."
L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "Abre la ventana de AuraBuffs, donde añades cada objeto por su ID de objeto e ID de hechizo de beneficio."
L["Opens the Consumable Bar's settings."] = "Abre la configuración de la barra de consumibles."
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "Abre la tarjeta de copia sobre un hechizo de ejemplo. Selecciona la ID o el enlace y pulsa Ctrl+C."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "Abre la configuración del seguimiento de misiones del Diario de mazmorras."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "Abre el Editor de HUD: haz clic en otro elemento de Naowh Forever con el que se moverá la barra."
L["Opens the Library Books tracker's settings."] = "Abre la configuración del seguimiento de Libros de la biblioteca."
L["Opens the planner on its Builds tab."] = "Abre el planificador en su pestaña Builds."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "Abre el seguimiento de misiones en el mundo, en la mazmorra a la que corresponden tus misiones."
L["Opens the quest tracker when you enter a dungeon with quests for you."] = "Abre el seguimiento de misiones al entrar en una mazmorra con misiones para ti."
L["Opens the quiz now, or closes it."] = "Abre el test ahora o lo cierra."
L["Opens the Run Timer settings."] = "Abre la configuración del Temporizador de run."
L["Opens the Sleeping Bag tracker's settings."] = "Abre la configuración del seguimiento del Saco de dormir."
L["Opens the Stat Weights window: each stat's worth to your spec, and your best upgrades by them."] = "Abre la ventana Pesos de estadísticas: lo que vale cada estadística para tu especialización y tus mejores mejoras según ellos."
