L["put down what you are holding first."] = "suelta antes lo que tienes en la mano."
L["Put every %s weight back to the defaults?"] = "¿Restablecer todos los pesos de %s a sus valores predeterminados?"
L["Put every setting back to how it was before the onboarding?"] = "¿Devolver todas las opciones a como estaban antes de la configuración inicial?"
L["Put every setting in this profile back to its default."] = "Devuelve todas las opciones de este perfil a su valor predeterminado."
L["Put on in cities and inns, and taken off again when you leave."] = "Se pone en ciudades y posadas, y se quita de nuevo al salir."
L["Put on while you ride, and the set you had on goes back when you dismount."] = "Se pone mientras vas montado, y el conjunto que llevabas vuelve al desmontar."
L["Put the XP Bar colors back to their defaults?"] = "¿Restablecer los colores de la barra de PX a sus valores predeterminados?"
