L["Takes everything the moment you loot, with Blizzard's loot window kept out of sight, so the feed is all you see. Works with or without the game's auto loot. Hold Shift while looting to get the window back. It also appears whenever something cannot be taken: a group roll, a locked item, or bags too full."] = "Lo coge todo en cuanto despojas, con la ventana de botín de Blizzard oculta, así que solo ves el registro. Funciona con o sin el despojo automático del juego. Mantén Mayús al despojar para recuperar la ventana. También aparece cuando algo no se puede coger: una tirada de grupo, un objeto bloqueado o bolsas demasiado llenas."
