L["What a point of each stat is worth to your spec."] = "Lo que vale un punto de cada estadística para tu especialización."
L["What a saved set brings back when you import it. Sets are saved and imported from the Action Bars window, out of combat."] = "Lo que recupera un conjunto guardado al importarlo. Los conjuntos se guardan e importan desde la ventana de Barras de acción, fuera de combate."
L["What a waypoint from the Discovery window or the tracker does."] = "Lo que hace un punto de ruta de la ventana de Descubrimiento o del seguimiento."
