L["Your BiS in your bags or bank: put it on."] = "Tu BiS está en tus bolsas o banco: póntelo."
L["Your BiS list is empty"] = "Tu lista BiS está vacía"
L["Your BiS list now keeps a ranked list per slot. These did not fit: "] = "Tu lista BiS ahora guarda una lista clasificada por casilla. Estos no cabían: "
L["Your BiS List's slot marks on the items in your bags: item level, your BiS's star, Forever's mark and the green arrow on an upgrade. In the game's bags or EllesmereUI's."] = "Las marcas de casilla de tu lista BiS en los objetos de tus bolsas: nivel de objeto, la estrella de tu BiS, la marca de Forever y la flecha verde en una mejora. En las bolsas del juego o en las de EllesmereUI."
L["Your BiS lists, for every class."] = "Tus listas BiS, para todas las clases."
L["Your BiS only"] = "Solo tu BiS"
L["Your BiS you do not have yet: where to go next."] = "El BiS que aún no tienes: adónde ir después."
L["Your BiS's star on a slot, and Forever's mark on what is new in Forever."] = "La estrella de tu BiS en una casilla y la marca de Forever en lo nuevo en Forever."
L["Your BiS, your second pick, and so on."] = "Tu BiS, tu segunda elección, etc."
L["Your buttons and a clock along the top."] = "Tus botones y un reloj en la parte superior."
L["Your buttons on either side of an optional clock, with FPS and latency underneath."] = "Tus botones a ambos lados de un reloj opcional, con FPS y latencia debajo."
L["Your buttons on either side of an optional clock, with FPS and latency underneath. Arrange the buttons in the preview: drag one to move it, its x removes it, a side's + adds one. Move the bar in the HUD Editor."] = "Tus botones a ambos lados de un reloj opcional, con FPS y latencia debajo. Ordena los botones en la vista previa: arrastra uno para moverlo, su x lo quita y el + de un lado añade uno. Mueve la barra en el Editor de HUD."
L["Your camp's bonuses and time left on screen, and a reminder when Camp Benefits runs out."] = "Las bonificaciones y el tiempo restante de tu campamento en pantalla, y un recordatorio cuando se acaban Beneficios de campamento."
L["Your camp's bonuses by the icon, always or while you hover it."] = "Las bonificaciones de tu campamento junto al icono, siempre o al pasar el cursor."
L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "Tu límite es %d.\nPrimero haz la misión %s%s|r (%shabilidad %d):"
L["Your cap is %d.\nFirst read %s (needs skill %d):"] = "Tu límite es %d.\nPrimero lee %s (requiere habilidad %d):"
