L["Your casts and channels swept around the ring too."] = "Tus lanzamientos y canalizaciones también barren alrededor del anillo."
L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "Tu panel de personaje (C) con el aspecto de la lista BiS: cada casilla con sus marcas, tus estadísticas para tu especialización y tu puntuación Naowh bajo tu nivel. El juego conserva el panel y todo lo que hace. Con EllesmereUI, activarlo desactiva su panel de personaje, y desactivarlo lo vuelve a activar, tras recargar."
