L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "Tu experiencia por hora en una pequeña tarjeta, con el tiempo para subir, tiempo jugado, duración de la sesión y tiempos de los niveles recientes. Oculta al nivel máximo. Pasa el cursor para Empezar, Pausar y Reiniciar (también /naowh xp start, pause o reset). Muévela en el Editor de HUD."
L["Your experience. Its left end is a darker shade."] = "Tu experiencia. Su extremo izquierdo es de un tono más oscuro."
L["Your flight on a card: time left, the stops on a track, and the next stop."] = "Tu vuelo en una tarjeta: tiempo restante, las paradas en un trayecto y la siguiente parada."
L["Your focus target's casts on a bar of their own, colored by whether your interrupt is ready, with a tick where it comes off cooldown and a shield on casts you cannot interrupt. Your interrupt is the first you know of Pummel, Shield Bash, Kick, Counterspell, Earth Shock, Silence and Feral Charge. Move it in the HUD Editor."] = "Los lanzamientos de tu foco en su propia barra, coloreada según si tu interrupción está lista, con una marca donde sale de reutilización y un escudo en los lanzamientos que no puedes interrumpir. Tu interrupción es la primera que conozcas de Zurrar, Azote de escudo, Patada, Contrahechizo, Choque de tierra, Silencio y Carga feral. Muévela en el Editor de HUD."
L["Your focus's name, tinted by class, with their class icon above the panel."] = "El nombre de tu foco, teñido por clase, con su icono de clase encima del panel."
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "Tu foco, puesto con NF Focus: sus temporizadores siguen contando mientras luchas contra otro."
L["Your game macros, not the Smart Macros, as one string to share."] = "Tus macros del juego, no las macros inteligentes, como una cadena para compartir."
L["Your global cooldown swept around the ring, and a ready ring once it is over."] = "Tu tiempo de reutilización global barrido alrededor del anillo, y un anillo de listo cuando termina."
L["YOUR GOLD"] = "TU ORO"
