L["Your level, experience and percentage on one bar, with the XP of completed quests and rested experience drawn past the fill. Replaces Blizzard's experience bar while it is on. Move it in the HUD Editor. Ctrl + right-click the bar to reset the session time and XP/Hour."] = "Tu nivel, experiencia y porcentaje en una barra, con los PX de las misiones completadas y la experiencia de descanso dibujados más allá del relleno. Sustituye a la barra de experiencia de Blizzard mientras está activada. Muévela en el Editor de HUD. Ctrl + clic derecho en la barra para reiniciar el tiempo de sesión y los PX/hora."
